    public static List<MarriageTopicItem> getAllTopics() {

        return new ArrayList<>(TOPICS);

    }



    public static List<MarriageTopicItem> getTopicsByCategory(String categoryBn) {

        if (categoryBn == null || categoryBn.isEmpty() || "সকল অধ্যায়".equals(categoryBn) || "সকল অধ্যায়".equals(categoryBn) || "All Chapters".equalsIgnoreCase(categoryBn)) {

            return getAllTopics();

        }

        List<MarriageTopicItem> filtered = new ArrayList<>();

        for (MarriageTopicItem item : TOPICS) {

            if (categoryBn.equals(item.getCategoryBn()) || categoryBn.equalsIgnoreCase(item.getCategoryEn())) {

                filtered.add(item);

            }

        }

        return filtered;

    }



    public static List<MarriageTopicItem> searchTopics(String query) {

        if (query == null || query.trim().isEmpty()) {

            return getAllTopics();

        }

        String q = query.trim().toLowerCase();

        List<MarriageTopicItem> filtered = new ArrayList<>();

        for (MarriageTopicItem item : TOPICS) {

            if (item.getTitleBn().toLowerCase().contains(q) ||

                item.getTitleEn().toLowerCase().contains(q) ||

                item.getSummaryBn().toLowerCase().contains(q) ||

                item.getSummaryEn().toLowerCase().contains(q) ||

                item.getContentBn().toLowerCase().contains(q) ||

                item.getContentEn().toLowerCase().contains(q) ||

                item.getReferences().toLowerCase().contains(q) ||

                item.getArabicMeaning().toLowerCase().contains(q)) {

                filtered.add(item);

            }

        }

        return filtered;

    }



    public static MarriageTopicItem getTopicById(int id) {

        for (MarriageTopicItem item : TOPICS) {

            if (item.getId() == id) {

                return item;

            }

        }

        return TOPICS.isEmpty() ? null : TOPICS.get(0);

    }

